import collections
c = collections.Counter()
with open(CATALOG_CSV) as f:
    next(f)
    for line in f:
        parts = line.strip().split(',')
        if len(parts) >= 2:
            c[parts[2]] += 1
for k,v in c.most_common():
    print(v, k)

